"""What a sheet draws: the parts with their symbols' pins, and the nets by kind.

Everything the placer and the router decide rests on three readings of the
plan, each the way an engineer reads a circuit before drawing it:

- a net is ground, a supply rail or a signal (ground symbols point down,
  supply symbols up, signals are wired and named);
- a part is a connector, an active part (anything with three pins or more)
  or a two-pin part;
- a two-pin part is either in the signal path (series: drawn horizontally,
  between what it joins) or hangs off a net (a shunt: drawn vertically, off
  the line it loads, supply above and ground below).
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any, Iterable, Optional

from eda_agent.design import sch_template as st

GRID = 100
#: A pin's outward direction by its orientation code (0 right, 1 up, 2 left, 3 down).
DIRS = {0: (1, 0), 1: (0, 1), 2: (-1, 0), 3: (0, -1)}
ROTATIONS = (0, 90, 180, 270)
#: An orientation is a rotation, plus MIRROR when the part is mirrored
#: (reflected left to right about its own x after the rotation, as
#: Altium mirrors): 0..270 plain, 360..630 mirrored.
MIRROR = 360
ORIENTATIONS = ROTATIONS + tuple(r + MIRROR for r in ROTATIONS)
#: How far Altium's part outline reaches past each pin (not the graphics).
OUTLINE_MARGIN = 20

UP, DOWN, LEFT, RIGHT = 1, 3, 2, 0

_GROUND = re.compile(
    r"^(?:[ADPSC]?GND\w*|\w*_GND|VSS\w*|0V|EARTH|PE|COM)$", re.I)
_POWER = re.compile(
    r"^(?:[+-]\w.*|V(?:CC|DD|EE|IN|BAT|BUS|SYS|OUT|IO|MOT|LED|USB|DRV|PP|\d)\w*"
    r"|\d+V\d*\w*|P\d+V\d*\w*)$", re.I)
_CONN_PREFIXES = {"J", "P", "X", "CN", "CON", "XS", "XP", "XJ", "USB", "JP"}
#: Two-pin parts that sit in a path even between a rail and a signal: an
#: inductor or bead is the path itself, never a shunt.
_ALWAYS_SERIES = {"L", "FB", "F", "FL", "FU"}
#: Words in a connector's role or value that fix its side of the sheet. A
#: connector with neither (a debug header, a bus) sits where its pins lead.
_INPUT_WORDS = {"in", "vin", "input", "inp", "ctrl", "control", "supply", "pwr",
                "power", "source", "src", "batt", "bat", "battery", "sense", "sensor"}
_OUTPUT_WORDS = {"out", "vout", "output", "load", "motor", "speaker", "sink",
                 "actuator", "lamp", "relay", "heater", "fan"}


def prefix(ref: str) -> str:
    m = re.match(r"[A-Za-z]+", ref)
    return m.group(0).upper() if m else ""


def _words(*texts: Optional[str]) -> set[str]:
    out: set[str] = set()
    for t in texts:
        out.update(w for w in re.split(r"[^a-z0-9]+", (t or "").lower()) if w)
    return out


@dataclass
class Symbol:
    """A library symbol: its visible pins (part 1), as lib_get_pin_list reads them."""
    lib_ref: str
    pins: list[dict]
    #: The symbol's graphics (rectangles, lines, polygons, arcs), symbol-
    #: local, as the library reports their bounding rectangles; None when
    #: not read (then the body is estimated from the pins).
    outline: Optional[tuple[int, int, int, int]] = None

    @classmethod
    def from_rows(cls, lib_ref: str, rows: Iterable[dict]) -> "Symbol":
        keep = []
        outline = None
        for p in rows:
            if "_outline" in p:
                box = [int(v) for v in p["_outline"]]
                outline = (min(box[0], box[2]), min(box[1], box[3]),
                           max(box[0], box[2]), max(box[1], box[3]))
                continue
            if int(p.get("display_mode", 0) or 0) != 0 or p.get("hidden") in (True, "true"):
                continue
            if int(p.get("owner_part_id", 1) or 0) not in (0, 1):
                continue
            keep.append(dict(p))
        return cls(lib_ref, keep, outline)

    def number_of(self, key: str) -> Optional[str]:
        """A plan pin (number or name) as the symbol's pin number."""
        key = str(key)
        for p in self.pins:
            if str(p.get("designator", "")) == key:
                return key
        named = [str(p.get("designator", "")) for p in self.pins if str(p.get("name", "")) == key]
        return named[0] if len(named) == 1 else None

    def body(self) -> tuple[int, int, int, int]:
        """The body at rotation 0, symbol-local, estimated from the pin roots.

        The pins give where the body edges are; when every pin leaves on one
        side (a connector) the body reaches back to the symbol origin, which
        library symbols put on the body.
        """
        if not self.pins:
            return self.outline or (0, 0, 0, 0)
        xs = [int(p.get("x", 0)) for p in self.pins]
        ys = [int(p.get("y", 0)) for p in self.pins]
        if self.outline:
            # The graphics as drawn, reaching at least to where the pins
            # meet the body.
            x0, y0, x1, y1 = self.outline
            return (min([x0] + xs), min([y0] + ys), max([x1] + xs), max([y1] + ys))
        def origin_behind(p: dict) -> bool:
            dx, dy = DIRS[int(p.get("orientation", 0)) % 4]
            return -int(p.get("x", 0)) * dx - int(p.get("y", 0)) * dy < 0

        one_side = len({int(p.get("orientation", 0)) % 4 for p in self.pins}) == 1
        if one_side and all(origin_behind(p) for p in self.pins):
            xs.append(0)
            ys.append(0)
        x0, x1, y0, y1 = min(xs), max(xs), min(ys), max(ys)
        half = 40 if len(self.pins) <= 2 else 50
        if x1 - x0 < 2 * half:
            mid = (x0 + x1) // 2
            x0, x1 = mid - half, mid + half
        if y1 - y0 < 2 * half:
            mid = (y0 + y1) // 2
            y0, y1 = mid - half, mid + half
        return (x0, y0, x1, y1)


def split(orientation: int) -> tuple[int, bool]:
    """An orientation as (rotation, mirrored)."""
    return orientation % MIRROR, orientation >= MIRROR


def rotate(x: int, y: int, rotation: int) -> tuple[int, int]:
    r, mirrored = split(rotation)
    if r == 90:
        x, y = -y, x
    elif r == 180:
        x, y = -x, -y
    elif r == 270:
        x, y = y, -x
    return (-x, y) if mirrored else (x, y)


def rotated_box(box: tuple[int, int, int, int], rotation: int) -> tuple[int, int, int, int]:
    pts = [rotate(box[0], box[1], rotation), rotate(box[2], box[3], rotation)]
    return (min(p[0] for p in pts), min(p[1] for p in pts),
            max(p[0] for p in pts), max(p[1] for p in pts))


@dataclass
class Part:
    ref: str
    lib_ref: str
    lib_path: str
    value: str
    role: str
    symbol: Symbol
    kind: str = "active"            # connector | active | two | one
    side: str = ""                  # connectors: left (an input) or right (an output)

    def pin_ends(self, x: int, y: int, rotation: int) -> list[st.PinEnd]:
        r, mirrored = split(rotation)
        return st.place_symbol_pins(self.ref, self.symbol.pins, x, y, r,
                                    mirrored=mirrored)

    def pin_offset(self, number: str, rotation: int) -> tuple[int, int, int]:
        """(dx, dy, orientation) of a pin's wire end from the part origin."""
        for p in self.pin_ends(0, 0, rotation):
            if p.number == number:
                return p.x, p.y, p.orientation
        raise KeyError(f"{self.ref} has no pin {number}")

    def rotation_facing(self, number: str, direction: int) -> Optional[int]:
        """The rotation that points pin ``number`` in ``direction``."""
        for r in ROTATIONS:
            if self.pin_offset(number, r)[2] == direction:
                return r
        return None

    def orientations_facing(self, number: str, direction: int) -> tuple[int, ...]:
        """Every orientation, mirrored ones included, that points pin
        ``number`` in ``direction``."""
        return tuple(o for o in ORIENTATIONS
                     if self.pin_offset(number, o)[2] == direction)


@dataclass
class Net:
    name: str
    kind: str                       # ground | power | signal
    pins: list[tuple[str, str]] = field(default_factory=list)

    @property
    def port_dir(self) -> Optional[int]:
        """Where its power symbol points: ground and negative rails down."""
        if self.kind == "ground" or (self.kind == "power" and self.name.startswith("-")):
            return DOWN
        if self.kind == "power":
            return UP
        return None

    @property
    def port_style(self) -> str:
        return "gnd_power" if self.kind == "ground" else "bar"


@dataclass
class Attachment:
    """A two-pin part hung off a net: which pin meets the net and how it hangs."""
    ref: str
    role: str                       # shunt_down | shunt_up | decap
    net: str                        # the net it hangs from (the lane)
    lane_pin: str                   # its pin on that net
    lane_facing: int                # the way that pin points once placed (UP or DOWN)


@dataclass
class Circuit:
    parts: dict[str, Part]
    nets: dict[str, Net]
    pin_net: dict[tuple[str, str], str]
    problems: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)

    def nets_of(self, ref: str) -> dict[str, str]:
        """pin number -> net for one part."""
        return {num: n for (r, num), n in self.pin_net.items() if r == ref}

    def attachment(self, ref: str) -> Optional[Attachment]:
        part = self.parts[ref]
        if part.kind != "two" or prefix(ref) in _ALWAYS_SERIES:
            return None
        a, b = (str(p.get("designator", "")) for p in part.symbol.pins)
        na, nb = self.pin_net.get((ref, a)), self.pin_net.get((ref, b))
        ka = self.nets[na].kind if na else "none"
        kb = self.nets[nb].kind if nb else "none"
        if ka == "ground" and kb == "ground":
            return None
        if "ground" in (ka, kb):
            lane_pin, lane = (b, nb) if ka == "ground" else (a, na)
            if lane is None:
                return None
            kind = self.nets[lane].kind
            if kind == "power" and self.nets[lane].port_dir == DOWN:
                return None             # a negative rail: draw it in the path
            return Attachment(ref, "decap" if kind == "power" else "shunt_down",
                              lane, lane_pin, UP)
        if {ka, kb} == {"power", "signal"}:
            lane_pin, lane = (b, nb) if ka == "power" else (a, na)
            return Attachment(ref, "shunt_up", lane, lane_pin, DOWN)
        return None


def classify_net(name: str, is_power: bool = False, is_ground: bool = False) -> str:
    if is_ground or _GROUND.match(name):
        return "ground"
    if is_power or _POWER.match(name):
        return "power"
    return "signal"


def connector_side(part: Part) -> str:
    """left (an input), right (an output) or "" (where its pins lead)."""
    words = _words(part.role, part.value)
    if words & _OUTPUT_WORDS and not words & {"in", "vin", "input"}:
        return "right"
    if words & _INPUT_WORDS:
        return "left"
    return ""


def from_plan(plan: Any, symbols: dict, sheet: str = "") -> Circuit:
    """The circuit of one plan sheet.

    ``plan`` is a DesignPlan (or its dict); ``symbols`` maps a lib_ref, or a
    (lib_path, lib_ref) pair, to the pin rows lib_get_pin_list returns.
    """
    data = plan.model_dump() if hasattr(plan, "model_dump") else dict(plan)
    sheets = [s.get("name") for s in data.get("sheets") or []]
    sheet = sheet or (sheets[0] if sheets else "main")
    parts: dict[str, Part] = {}
    problems: list[str] = []
    notes: list[str] = []
    for p in data.get("parts") or []:
        if (p.get("sheet") or "main") != sheet:
            continue
        ref, lib_ref, lib_path = p["refdes"], p["lib_ref"], p.get("lib_path") or ""
        rows = symbols.get((lib_path, lib_ref), symbols.get(lib_ref))
        if not rows:
            problems.append(f"{ref}: no pins read for symbol {lib_ref}")
            continue
        sym = Symbol.from_rows(lib_ref, rows)
        owners = {int(r.get("owner_part_id", 1) or 0) for r in rows}
        if len(owners - {0}) > 1:
            notes.append(f"{ref}: a multi-part symbol; only part 1 is drafted")
        off = [str(r.get("designator")) for r in sym.pins
               if int(r.get("x", 0)) % GRID or int(r.get("y", 0)) % GRID
               or int(r.get("length", 0)) % GRID]
        if off:
            problems.append(f"{ref}: pins {', '.join(off)} of {lib_ref} are off the "
                            f"{GRID} mil grid; fix the symbol first")
        part = Part(ref, lib_ref, lib_path, str(p.get("value") or ""),
                    str(p.get("role") or ""), sym)
        n = len(sym.pins)
        if prefix(ref) in _CONN_PREFIXES or "conn" in _words(part.role) \
                or "connector" in _words(part.role):
            part.kind = "connector"
        elif n == 2:
            part.kind = "two"
        elif n == 1:
            part.kind = "one"
        parts[ref] = part
    nets: dict[str, Net] = {}
    pin_net: dict[tuple[str, str], str] = {}
    # A plan that flags its rails says which nets are rails: then a name
    # like VIN on an amplifier's input stays a signal.
    flagged = any(n.get("is_power") or n.get("is_ground") for n in data.get("nets") or [])
    for n in data.get("nets") or []:
        if flagged:
            kind = "ground" if n.get("is_ground") else "power" if n.get("is_power") else "signal"
        else:
            kind = classify_net(n["name"])
        net = Net(n["name"], kind)
        for pr in n.get("pins") or []:
            ref = pr["refdes"]
            if ref not in parts:
                continue
            num = parts[ref].symbol.number_of(pr["pin"])
            if num is None:
                problems.append(f"{n['name']}: {ref} has no pin {pr['pin']}")
                continue
            if (ref, num) in pin_net:
                problems.append(f"{ref}.{num} is on {pin_net[(ref, num)]} and {n['name']}")
                continue
            pin_net[(ref, num)] = net.name
            net.pins.append((ref, num))
        if net.pins:
            nets[net.name] = net
    for part in parts.values():
        if part.kind == "connector":
            part.side = connector_side(part)
    return Circuit(parts, nets, pin_net, problems, notes)
